'use strict';
const $=s=>document.querySelector(s), keys=['disc','shell','label','stickers'], layerNames=['圆形盘面','塑料外壳','右侧标签','左侧贴纸'];
let state=MD.preset(0),layer='disc',mode='assembled',history=[],future=[],pending=false,timer;
try{const saved=localStorage.getItem('md-atelier-v1');if(saved)state=validate(JSON.parse(saved));}catch{}
function validate(raw){if(!raw||raw.version!==1||!Number.isInteger(raw.template)||raw.template<0||raw.template>11)throw Error('不是有效的 MiniDisc Atelier 参数文件');const t=MD.preset(raw.template),num=(v,min,max)=>{if(typeof v!=='number'||!Number.isFinite(v))throw Error('参数数值无效');return MD.clamp(v,min,max);};t.seed=num(raw.seed,0,4294967295);for(const k of keys){const a=raw[k],b=t[k];if(!a||typeof a!=='object')throw Error('缺少图层数据');for(const p of Object.keys(b)){if(p==='p'){if(!Array.isArray(a.p)||a.p.length!==4)throw Error('参数组无效');b.p=a.p.map((v,i)=>num(v,k==='stickers'&&i===0?1:0,k==='stickers'&&i===0?5:100));b.p[0]=k==='stickers'?Math.round(b.p[0]):b.p[0];}else if(['color','accent','paper','ink'].includes(p)){if(!/^#[0-9a-f]{6}$/i.test(a[p]))throw Error('颜色格式无效');b[p]=a[p];}else if(['title','subtitle','code'].includes(p)){if(typeof a[p]!=='string')throw Error('文字格式无效');b[p]=a[p].slice(0,p==='code'?20:80);}else if(['visible','locked'].includes(p)){b[p]=a[p]!==false;if(p==='locked')b[p]=a[p]===true;}else{let min=0,max=100;if(['program','texture','font','style'].includes(p))max=11;if(p==='saturation'||p==='brightness')max=200;if(p==='size'){min=12;max=64;}if(p==='tracking'){min=-3;max=8;}if(p==='angle'){min=-15;max=15;}b[p]=num(a[p],min,max);if(['program','texture','font','style'].includes(p))b[p]=Math.round(b[p]);}}}return t;}
function checkpoint(){history.push(MD.clone(state));if(history.length>60)history.shift();future=[];buttons();}
function buttons(){$('#undo').disabled=!history.length;$('#redo').disabled=!future.length;}
function persist(){try{localStorage.setItem('md-atelier-v1',JSON.stringify(state));}catch{}}
function notify(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),2600);}
function draw(){const opts={id:'preview'};if(mode==='exploded')opts.exploded=true;if(mode==='solo')opts.solo=layer;$('#art').innerHTML=MD.render(state,opts);$('#work-title').textContent=MD.names[state.template];$('#work-genre').textContent=MD.genres[state.template];$('#note').textContent=MD.notes[state.template];$('#view-label').textContent=mode==='assembled'?'ASSEMBLED · 4 LAYERS':mode==='exploded'?'EXPLODED · LAYER STUDY':'SOLO · '+layer.toUpperCase();$('.stage-caption span').textContent='MD—'+String(state.template+1).padStart(2,'0')+' / FRONT VIEW';persist();buttons();}
function schedule(){if(pending)return;pending=true;requestAnimationFrame(()=>{pending=false;draw();});}
function chooseTemplate(i){checkpoint();state=MD.preset(i);refresh();notify('已载入 '+MD.names[i]+' · 可继续编辑');}
function thumbs(){const el=$('#templates');el.innerHTML=MD.names.map((name,i)=>`<button class="template ${i===state.template?'active':''}" data-template="${i}" title="${MD.esc(MD.genres[i])}"><img width="47" height="47" alt="" src="data:image/svg+xml,${encodeURIComponent(MD.render(MD.preset(i),{id:'thumb'+i}))}"><span><strong>${MD.esc(MD.genres[i].split(' / ').slice(0,2).join(' / '))}</strong><small>${String(i+1).padStart(2,'0')} — ${name.toUpperCase()}</small></span></button>`).join('');el.querySelectorAll('button').forEach(b=>b.onclick=()=>chooseTemplate(+b.dataset.template));}
function range(key,label,min=0,max=100,step=1,suffix=''){const val=key.startsWith('p.')?state[layer].p[+key.slice(2)]:state[layer][key];return `<div class="field"><label for="f-${key.replace('.','-')}">${label}<output>${val}${suffix}</output></label><input id="f-${key.replace('.','-')}" data-field="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${val}" ${state[layer].locked?'disabled':''}></div>`;}
function color(key,label){return `<div class="field"><label for="f-${key}">${label}</label><input type="color" id="f-${key}" data-field="${key}" value="${state[layer][key]}" ${state[layer].locked?'disabled':''}></div>`;}
function select(key,label,values){return `<div class="field"><label for="f-${key}">${label}</label><select id="f-${key}" data-field="${key}" ${state[layer].locked?'disabled':''}>${values.map((v,i)=>`<option value="${i}" ${state[layer][key]===i?'selected':''}>${String(i+1).padStart(2,'0')} · ${MD.esc(v)}</option>`).join('')}</select></div>`;}
function textField(key,label){return `<div class="field"><label for="f-${key}">${label}</label><input type="text" id="f-${key}" data-field="${key}" maxlength="${key==='code'?20:80}" value="${MD.esc(state[layer][key]).replace(/\n/g,' / ')}" ${state[layer].locked?'disabled':''}></div>`;}
function controls(){const idx=keys.indexOf(layer),l=state[layer];$('#layers').innerHTML=keys.map((k,i)=>`<button data-layer="${k}" class="${k===layer?'active':''}"><small>0${i+1}</small>${['盘面','外壳','标签','贴纸'][i]}</button>`).join('');$('#layers').querySelectorAll('button').forEach(b=>b.onclick=()=>{layer=b.dataset.layer;controls();if(mode==='solo')draw();});let h=`<div class="section-label">0${idx+1} / ${layerNames[idx]}<small>${layer.toUpperCase()}</small></div><div class="switches"><button id="visible">${l.visible?'◉ 图层可见':'○ 图层隐藏'}</button><button id="lock">${l.locked?'▣ 已锁定':'□ 随机时可变'}</button></div>`;
if(layer==='disc'){h+=select('program','视觉程序',MD.programs.map(x=>x[0]+' / '+x[1]))+'<div class="colors">'+color('color','盘面底色')+color('accent','印刷 / 虹彩色')+'</div><div class="section-label">程序参数<small>4 MACRO CONTROLS</small></div>';MD.programs[l.program][2].forEach((label,i)=>h+=range('p.'+i,label));}
if(layer==='shell'){h+=select('texture','注塑材质',MD.textures)+color('color','塑料透色')+range('transparency','材质透光',0,100,1,'%')+range('blur','透壳雾化',0,100,1,'%')+range('relief','纹理浮凸',0,100,1,'%')+range('wear','旧化划痕',0,100,1,'%')+'<p class="hint">透光控制塑料着色，雾化柔化壳内盘面。边缘、模压细节与高光独立保留。</p>';}
if(layer==='label'){h+=select('font','字体风格',MD.fonts.map(x=>x[0]+' / '+x[1]))+textField('title','主标题 · 输入 / 可换行')+textField('subtitle','副标题')+textField('code','档案编号')+'<div class="colors">'+color('paper','标签纸色')+color('ink','印刷墨色')+'</div>'+range('size','字号上限',12,64)+range('tracking','字距',-3,8,.5)+range('angle','标签倾角',-15,15,1,'°')+'<button id="random-text" class="full" '+(l.locked?'disabled':'')+'>⤨ 随机唱片标题</button><p class="hint">长标题会自动缩小以适应标签。字体使用本机字体，SVG 保留可编辑文字。</p>';}
if(layer==='stickers'){h+=select('style','贴纸系列',MD.stickerStyles)+'<div class="colors">'+color('color','纸面 / 贴纸色')+color('ink','印刷颜色')+'</div><div class="section-label">贴纸参数<small>4 MACRO CONTROLS</small></div>'+range('p.0','贴纸数量',1,5)+range('p.1','整体尺寸',0,100,1,'%')+range('p.2','随机倾角',0,100,1,'%')+range('p.3','位置散布',0,100,1,'%')+'<p class="hint">贴纸保持在左侧区域；改变随机种子重新组合位置，同一参数可重复生成。</p>';}
h+='<div class="divider"></div><div class="section-label">图层色调<small>COMPOSITING</small></div>'+range('opacity','图层透明度',0,100,1,'%')+range('saturation','饱和度',0,200,1,'%')+range('brightness','明度',0,200,1,'%')+`<button id="random-layer" class="full" ${l.locked?'disabled':''}>⤨ 随机当前层</button>`;$('#controls').innerHTML=h;
$('#visible').onclick=()=>{checkpoint();l.visible=!l.visible;refresh();};$('#lock').onclick=()=>{checkpoint();l.locked=!l.locked;refresh();};$('#random-layer').onclick=()=>randomize(false);if($('#random-text'))$('#random-text').onclick=()=>{checkpoint();randomText();refresh();};
$('#controls').querySelectorAll('[data-field]').forEach(el=>{el.addEventListener('focus',()=>{el.dataset.started='';});el.addEventListener('pointerdown',()=>{el.dataset.started='';});el.addEventListener('input',()=>{if(!el.dataset.started){checkpoint();el.dataset.started='1';}let k=el.dataset.field,v=el.type==='text'?el.value:el.type==='color'?el.value:Number(el.value);if(k==='title')v=v.replace(/\s*\/\s*/g,'\n');if(k.startsWith('p.'))l.p[+k.slice(2)]=v;else l[k]=v;if(el.type==='range'){let output=el.previousElementSibling.querySelector('output');output.textContent=v+(output.textContent.endsWith('%')?'%':output.textContent.endsWith('°')?'°':'');}if(el.tagName==='SELECT')controls();schedule();});});}
function randomText(){const a=['VELVET','SILENT','LOST','NEON','SOFT','LUNAR','DEEP','AFTER'],b=['MEMORY','SIGNAL','GARDEN','ECHO','RADIO','CURRENT','HOURS','DREAM'];state.label.title=a[Math.floor(Math.random()*a.length)]+'\n'+b[Math.floor(Math.random()*b.length)];state.label.code='MD-'+String(Math.floor(Math.random()*999)).padStart(3,'0');}
function randomize(all){checkpoint();let r=()=>Math.floor(Math.random()*100);const pal=MD.palettes[Math.floor(Math.random()*12)];for(const key of keys){const l=state[key];if(l.locked||(!all&&key!==layer))continue;if(key==='disc'){l.program=Math.floor(Math.random()*12);l.p=l.p.map(()=>15+r()*.75);l.p=l.p.map(Math.round);l.color=pal[0];l.accent=pal[1];}if(key==='shell'){l.texture=Math.floor(Math.random()*12);l.color=pal[2];l.transparency=72+r()*.25;l.blur=r()*.35;l.relief=35+r()*.6;Object.keys(l).forEach(k=>{if(typeof l[k]==='number')l[k]=Math.round(l[k]);});}if(key==='label'){l.font=Math.floor(Math.random()*12);l.paper=pal[3];randomText();}if(key==='stickers'){l.style=Math.floor(Math.random()*12);l.p=[1+r()%3,45+r()*.4,10+r()*.6,15+r()*.6].map(Math.round);l.color=pal[3];l.ink=pal[0];}}
// Keep locked procedural layers pixel-identical; seed changes have a separate explicit action.
refresh();notify(all?'已生成新变奏 · 锁定图层保留':'已随机当前层');}
function refresh(){draw();controls();$('#templates').querySelectorAll('button').forEach((b,i)=>b.classList.toggle('active',i===state.template));}
function download(content,type,name){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function filename(){return MD.names[state.template].toLowerCase().replaceAll(' ','-');}
$('#export').onclick=()=>{download(MD.render(state), 'image/svg+xml',filename()+'.svg');notify('SVG 已导出 · 完整合成 / 四个独立图层');};
$('#save').onclick=()=>{download(JSON.stringify(state,null,2),'application/json',filename()+'.json');notify('参数已保存，可重新载入继续编辑');};
$('#import').onclick=()=>$('#file').click();$('#file').onchange=async()=>{try{const file=$('#file').files[0];if(!file)return;if(file.size>100000)throw Error('参数文件过大');const s=validate(JSON.parse(await file.text()));checkpoint();state=s;refresh();notify('已恢复参数与四层设置');}catch(e){notify('载入失败：'+e.message);}$('#file').value='';};
$('#contact').onclick=()=>{let grid='';for(let i=0;i<12;i++){let x=30+i%4*360,y=60+Math.floor(i/4)*400;grid+=`<g transform="translate(${x} ${y})"><g transform="scale(.57)">${MD.render(MD.preset(i),{id:'sheet'+i}).replace(/<svg[^>]*>/,'').replace(/<\/svg>$/,'')}</g><text x="30" y="352" fill="#d5e5b7" font-family="Arial" font-size="13">${String(i+1).padStart(2,'0')} / ${MD.esc(MD.names[i])}</text><text x="30" y="373" fill="#96a48b" font-family="Arial" font-size="9">${MD.esc(MD.genres[i])}</text></g>`;}download(`<svg xmlns="http://www.w3.org/2000/svg" width="1500" height="1300" viewBox="0 0 1500 1300"><rect width="1500" height="1300" fill="#1c211c"/><text x="60" y="36" fill="#e1eace" font-family="Arial" font-size="15" letter-spacing="3">MINIDISC ATELIER / MUSIC ARCHIVE 001—012</text>${grid}</svg>`,'image/svg+xml','minidisc-12-genres.svg');notify('12 款原始模板图鉴已导出');};
$('#random-all').onclick=()=>randomize(true);$('#reset').onclick=()=>{checkpoint();state=MD.preset(state.template);refresh();notify('已恢复当前模板，可撤销');};
$('#undo').onclick=()=>{if(!history.length)return;future.push(MD.clone(state));state=history.pop();refresh();};$('#redo').onclick=()=>{if(!future.length)return;history.push(MD.clone(state));state=future.pop();refresh();};
document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select'))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();$(e.shiftKey?'#redo':'#undo').click();}});
for(const k of ['assembled','exploded','solo'])$('#'+k).onclick=()=>{mode=k;for(const n of ['assembled','exploded','solo'])$('#'+n).classList.toggle('active',k===n);draw();};
for(const k of ['dark','light','grid'])$('#bg-'+k).onclick=()=>{$('#stage').className='stage '+(k==='dark'?'':k);for(const n of ['dark','light','grid'])$('#bg-'+n).classList.toggle('active',n===k);};
thumbs();refresh();window.Atelier={get state(){return state;},validate,chooseTemplate,render:MD.render};
